using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class StairACapture {
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_T02_StairA/"));
 static void Shot(string n,Vector3 pos,Vector3 target,float fov){var go=new GameObject("StairA_Review_Temporary");var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.03f;c.farClipPlane=180;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");Directory.CreateDirectory(O);try{Shot(prefix+"_T02",new Vector3(-29.2f,-80.35f,21.27f),new Vector3(-40.2f,-80.8f,26.27f),77);Shot(prefix+"_VA_Entry",new Vector3(-40.7f,-80.35f,26.65f),new Vector3(-44.8f,-79.8f,28.0f),88);Shot(prefix+"_VA_South",new Vector3(-44,-80.35f,23.8f),new Vector3(-44,-78.9f,29),87);Shot(prefix+"_VA_Return",new Vector3(-46,-80.35f,25),new Vector3(-40.3f,-80.3f,26.4f),86);if(prefix=="After"){Shot(prefix+"_VA_Up",new Vector3(-43.04f,-78.35f,30.65f),new Vector3(-44,-70,28),84);Shot(prefix+"_VA_B4Landing",new Vector3(-44.96f,-64.35f,28.6f),new Vector3(-43.04f,-64.6f,25.1f),80);}}finally{EditorSceneManager.OpenScene(s.path);}return new{prefix,output=O};}
}
